  'est.eyebrow': { ar: "تقدير مجاني وفوري", fr: "Estimation gratuite et immédiate", es: "Valoración gratuita e inmediata", en: 'Free, instant valuation' },
  'est.title': { ar: "كم يساوي عقاركم اليوم؟", fr: "Combien vaut votre bien aujourd’hui ?", es: "¿Cuánto vale hoy su inmueble?", en: 'What is your property worth today?' },
  'est.subtitle': { ar: "تقدير أولي مبني على عقارات مشابهة معروضة لدينا في نفس الحي، ثم تقييم دقيق مجاني يقوم به خبيرنا.", fr: "Une première estimation fondée sur les biens comparables que nous proposons dans le même quartier, puis une évaluation précise et gratuite par notre expert.", es: "Una primera valoración basada en inmuebles comparables que ofrecemos en el mismo barrio, y después una tasación precisa y gratuita de nuestro experto.", en: 'A first estimate based on comparable properties we offer in the same neighbourhood, then a precise, free valuation by our expert.' },
