  'est.furnished': { ar: "مفروش", fr: "Meublé", es: "Amueblado", en: 'Furnished' },
  'est.fill': { ar: "اختاروا النوع والحي واكتبوا المساحة ليظهر التقدير.", fr: "Choisissez le type, le quartier et la surface pour voir l’estimation.", es: "Elija el tipo, el barrio y la superficie para ver la valoración.", en: 'Choose the type, neighbourhood and area to see the estimate.' },
  'est.none': { ar: "لا تتوفر لدينا معطيات كافية لهذا النوع في هذا الحي. اطلبوا تقييماً مجانياً يقوم به خبيرنا.", fr: "Nous n’avons pas assez de données pour ce type de bien dans ce quartier. Demandez une évaluation gratuite par notre expert.", es: "No tenemos datos suficientes para este tipo de inmueble en este barrio. Solicite una tasación gratuita de nuestro experto.", en: 'We do not have enough data for this type of property in this neighbourhood. Ask our expert for a free valuation.' },
