  'est.conf.high': { ar: "دقة جيدة (عروض كثيرة مشابهة)", fr: "Bonne précision (nombreux biens comparables)", es: "Buena precisión (muchos comparables)", en: 'Good accuracy (many comparable properties)' },
  'est.conf.medium': { ar: "دقة متوسطة", fr: "Précision moyenne", es: "Precisión media", en: 'Medium accuracy' },
