  'stays.none': { ar: 'لا توجد حالياً عقارات للكراء الموسمي. راسلونا عبر واتساب وسنبحث لكم.', fr: 'Aucune location saisonnière pour le moment. Écrivez-nous sur WhatsApp, nous chercherons pour vous.', es: 'No hay alquileres vacacionales por ahora. Escríbanos por WhatsApp y buscaremos por usted.', en: 'No holiday rentals at the moment. Message us on WhatsApp and we will search for you.' },
  'stays.waMsg': { ar: 'السلام عليكم، أبحث عن كراء لأيام العطلة في مرتيل أو المضيق.', fr: 'Bonjour, je cherche une location de vacances à Martil ou M’diq.', es: 'Hola, busco un alquiler vacacional en Martil o M’diq.', en: 'Hello, I am looking for a holiday rental in Martil or M’diq.' },
  'stays.how': { ar: 'كيف يتم الحجز؟', fr: 'Comment réserver ?', es: '¿Cómo reservar?', en: 'How to book?' },
  'stays.s1.t': { ar: 'اختاروا التواريخ', fr: 'Choisissez vos dates', es: 'Elija sus fechas', en: 'Choose your dates' },
  'stays.s1.d': { ar: 'تقويم التوفر محيّن، والثمن يُحسب مباشرة مع التنظيف وتخفيض الأسبوع.', fr: 'Calendrier à jour et prix calculé aussitôt, ménage et remise semaine compris.', es: 'Calendario actualizado y precio calculado al instante, con limpieza y descuento semanal.', en: 'An up-to-date calendar and the price calculated straight away, cleaning and weekly discount included.' },
  'stays.s2.t': { ar: 'أرسلوا الطلب', fr: 'Envoyez la demande', es: 'Envíe la solicitud', en: 'Send the request' },
  'stays.s2.d': { ar: 'نتصل بكم بسرعة لتأكيد التوفر والإجابة عن أسئلتكم، دون أي التزام.', fr: 'Nous vous recontactons vite pour confirmer la disponibilité, sans engagement.', es: 'Le contactamos enseguida para confirmar la disponibilidad, sin compromiso.', en: 'We get back to you quickly to confirm availability, with no commitment.' },
  'stays.s3.t': { ar: 'أكدوا بالعربون', fr: 'Confirmez avec l’acompte', es: 'Confirme con la señal', en: 'Confirm with the deposit' },
  'stays.s3.d': { ar: 'يُؤكَّد الحجز بأداء العربون ونرسل لكم وصل الحجز. الباقي والضمانة عند الوصول.', fr: 'La réservation est confirmée à réception de l’acompte, avec un reçu. Le solde et la caution à l’arrivée.', es: 'La reserva se confirma con la señal y le enviamos el recibo. El resto y la fianza a la llegada.', en: 'The booking is confirmed once the deposit is received, with a receipt. The balance and the security deposit are paid on arrival.' },
  'stays.legal.t': { ar: 'إقامة قانونية ومطمئنة', fr: 'Un séjour en règle', es: 'Una estancia en regla', en: 'A stay by the rules' },
  'stays.legal.d': { ar: 'نصرّح بالنزلاء كما يفرض القانون 80.14 المتعلق بمؤسسات الإيواء السياحي، ولذلك نطلب وثيقة هوية لكل نزيل بالغ عند الوصول. وتُرجع الضمانة بعد معاينة العقار عند المغادرة.', fr: 'Nous déclarons les voyageurs comme l’exige la loi 80-14 relative aux établissements d’hébergement touristique : une pièce d’identité est donc demandée à chaque adulte à l’arrivée. La caution est rendue après l’état des lieux de départ.', es: 'Declaramos a los huéspedes como exige la ley 80-14 sobre establecimientos de alojamiento turístico: por eso pedimos un documento de identidad a cada adulto a la llegada. La fianza se devuelve tras revisar el alojamiento a la salida.', en: 'We register our guests as required by law 80-14 on tourist accommodation, so an ID document is requested from each adult on arrival. The security deposit is returned after the check-out inspection.' },
  'stays.owner.t': { ar: 'لديكم شقة قرب البحر؟', fr: 'Vous avez un logement près de la mer ?', es: '¿Tiene una vivienda cerca del mar?', en: 'Do you own a home near the sea?' },
  'stays.owner.d': { ar: 'نكريها لكم في الصيف بالليلة أو بالأسبوع: الاستقبال، التنظيف، التصريح بالنزلاء، وتتوصلون بحصتكم مع كشف مفصل.', fr: 'Nous la louons pour vous l’été, à la nuit ou à la semaine : accueil, ménage, déclaration des voyageurs, et votre part versée avec un relevé détaillé.', es: 'La alquilamos por usted en verano, por noches o semanas: recepción, limpieza, declaración de huéspedes, y le transferimos su parte con un extracto detallado.', en: 'We rent it out for you in summer, by the night or by the week: welcome, cleaning, guest registration, and your share paid with a detailed statement.' },
